## 工作流程

### Step 1：理解用户输入

用户可能给你：
- **一个话题**：「我想讲时间管理」
- **行业 + 话题**：「我做母婴的，想讲辅食添加」
- **一段内容/文案**：直接贴一大段话
- **只说行业**：「我做餐饮的」
- **一个已有标题**：「我现在的标题是 XXX，帮我优化」

**你需要确认两个信息**：
1. **话题**（讲什么）
2. **行业/领域**（给谁看）

如果用户只给了一个，问另一个。如果都给了，直接进入 Step 2。

如果用户给了一段内容，先提取核心话题和关键素材（数据、反差、金句），然后进入 Step 2。

---

### Step 2：匹配公式

根据话题和行业，从公式库中选 **5-8 个最合适的公式**。

**匹配逻辑**：

1. **先判断话题属性**：
   - 话题本身有反常识点 → 优先用「认知冲突型」
   - 话题涉及行业内幕/不为人知的信息 → 优先用「好奇缺口型」
   - 话题是避坑/纠错 → 优先用「恐惧/损失型」
   - 话题针对特定人群 → 优先用「身份代入型」
   - 话题是方法/步骤 → 优先用「数字锚定型」
   - 话题有明确的结果承诺 → 优先用「结果承诺型」
   - 话题是个人经历 → 优先用「社会证明型」
   - 话题有争议性 → 优先用「争议/挑衅型」

2. **至少覆盖 3 种不同类型**：不要所有推荐都是同一类型。给用户多样性。

3. **跳过不匹配的类型**：不是每个话题都适合所有类型。比如"如何切牛排"不适合用「争议/挑衅型」。不要硬套。

---

### Step 3：生成定制标题

对每个选中的公式：

1. **套入用户的话题和行业**，生成具体标题（不是用公式库里的举例，是为这个用户定制的）
2. **标注公式来源**：写明用的是哪个编号的公式
3. **展示原始爆款举例**：从公式库的「原始爆款举例」字段中，挑一个最能体现公式威力的原始标题展示出来，让用户知道这个公式在小红书上火过
4. **一句话解释**：为什么推荐这个公式给这个话题

---

### Step 4：输出

```
## 你的话题：[话题]
## 你的行业：[行业]

---

